-- Function: public.sp_upsert_tenant_preferences
-- Backup generated on 2026-11-11 09:06:10

CREATE OR REPLACE PROCEDURE public.sp_upsert_tenant_preferences(IN p_tenant_id uuid, IN p_currency character varying, IN p_time_zone character varying, IN p_operating_hours_json jsonb, IN p_statutory_ratios_json jsonb, IN p_billing_rules_json jsonb, IN p_safety_policies_json jsonb, IN p_custom_settings_json jsonb)  LANGUAGE plpgsql AS $procedure$ BEGIN     INSERT INTO public.tenant_preferences (         tenant_id, currency, time_zone,         operating_hours_json, statutory_ratios_json,         billing_rules_json, safety_policies_json,         custom_settings_json, updated_at     ) VALUES (         p_tenant_id, p_currency, p_time_zone,         COALESCE(p_operating_hours_json, '{"openTime": "08:00", "closeTime": "18:00", "workingDays": ["Monday","Tuesday","Wednesday","Thursday","Friday"]}'::jsonb),         COALESCE(p_statutory_ratios_json, '{"Infant": 4, "Toddler": 7, "Preschool": 10, "Kindergarten": 15}'::jsonb),         COALESCE(p_billing_rules_json, '{"siblingDiscountPercent": 10.0, "latePickupFeePerMinute": 1.0, "gracePeriodMinutes": 15, "invoiceDueDays": 15}'::jsonb),         COALESCE(p_safety_policies_json, '{"napCheckIntervalMinutes": 15, "requireDualMedicationSignoff": false, "minEmergencyContacts": 2}'::jsonb),         COALESCE(p_custom_settings_json, '{}'::jsonb),         now()     )     ON CONFLICT (tenant_id) DO UPDATE SET         currency = EXCLUDED.currency,         time_zone = EXCLUDED.time_zone,         operating_hours_json = EXCLUDED.operating_hours_json,         statutory_ratios_json = EXCLUDED.statutory_ratios_json,         billing_rules_json = EXCLUDED.billing_rules_json,         safety_policies_json = EXCLUDED.safety_policies_json,         custom_settings_json = EXCLUDED.custom_settings_json,         updated_at = now(); END; $procedure$ ;
